import functools
import time

def retry(max_attempts: int = 3, delay: float = 1.0):
    """
    A decorator that retries a function call multiple times if an exception is raised.

    Args:
        max_attempts (int): The maximum number of times to attempt the function call.
        delay (float): The time in seconds to wait between attempts.

    Returns:
        callable: The decorated function.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None

            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_exception = e
                    print(f"Attempt {attempt} failed: {e}. Retrying in {delay}s...")
                    if attempt < max_attempts:
                        time.sleep(delay)

            print(f"All {max_attempts} attempts failed.")
            raise last_exception

        return wrapper
    return decorator

# --- Demonstration ---

if __name__ == "__main__":
    # Example 1: A function that fails twice then succeeds
    counter = 0

    @retry(max_attempts=3, delay=0.5)
    def unstable_function():
        global counter
        counter += 1
        if counter < 3:
            raise ValueError("Temporary error encountered!")
        return "Success!"

    print("Running unstable_function...")
    try:
        result = unstable_function()
        print(f"Result: {result}")
    except Exception as e:
        print(f"Final failure: {e}")

    print("\n" + "-"*30 + "\n")

    # Example 2: A function that always fails
    @retry(max_attempts=3, delay=0.5)
    def failing_function():
        raise RuntimeError("Permanent failure!")

    print("Running failing_function...")
    try:
        result = failing_function()
        print(f"Result: {result}")
    except Exception as e:
        print(f"Caught final exception: {e}")
